description:
Write the camera helpers of lesson 4.01 (no rotation):

```cpp
struct Vector2 { float x, y; };
struct Camera2D { Vector2 offset, target; float rotation, zoom; };

Vector2 worldToScreen(Vector2 p, const Camera2D& c);    // (p - target) * zoom + offset
Vector2 screenToWorld(Vector2 p, const Camera2D& c);
Vector2 deadZone(Vector2 target, Vector2 player, float halfW, float halfH);
Vector2 smoothTowards(Vector2 from, Vector2 to, float keepPerSecond, float dt);
Vector2 clampToLevel(Vector2 target, float screenW, float screenH, float zoom, float levelW, float levelH);
```

- `deadZone`: the player may be up to `halfW` and `halfH` away from the target on each axis; if further, the target moves just enough to bring the player back to the edge of that box.
- `smoothTowards`: the remaining distance shrinks to `keepPerSecond` of itself each second: `from + (to - from) * (1 - keepPerSecond^dt)`.
- `clampToLevel`: the visible area is `screenW / zoom` by `screenH / zoom` around the target. Keep it inside `0..levelW` and `0..levelH`. On an axis where the level is smaller than the visible area, centre on the level instead.

starter.solution.cpp:
struct Vector2 { float x, y; };
struct Camera2D { Vector2 offset, target; float rotation, zoom; };

Vector2 worldToScreen(Vector2 p, const Camera2D& c) { return p; }
Vector2 screenToWorld(Vector2 p, const Camera2D& c) { return p; }
Vector2 deadZone(Vector2 target, Vector2 player, float halfW, float halfH) { return target; }
Vector2 smoothTowards(Vector2 from, Vector2 to, float keepPerSecond, float dt) { return from; }
Vector2 clampToLevel(Vector2 target, float screenW, float screenH, float zoom, float levelW, float levelH) { return target; }

solution.solution.cpp:
#include <algorithm>
#include <cmath>

struct Vector2 { float x, y; };
struct Camera2D { Vector2 offset, target; float rotation, zoom; };

Vector2 worldToScreen(Vector2 p, const Camera2D& c)
{
    return { (p.x - c.target.x) * c.zoom + c.offset.x, (p.y - c.target.y) * c.zoom + c.offset.y };
}

Vector2 screenToWorld(Vector2 p, const Camera2D& c)
{
    return { (p.x - c.offset.x) / c.zoom + c.target.x, (p.y - c.offset.y) / c.zoom + c.target.y };
}

Vector2 deadZone(Vector2 target, Vector2 player, float halfW, float halfH)
{
    target.x = std::clamp(target.x, player.x - halfW, player.x + halfW);
    target.y = std::clamp(target.y, player.y - halfH, player.y + halfH);
    return target;
}

Vector2 smoothTowards(Vector2 from, Vector2 to, float keepPerSecond, float dt)
{
    const float t{ 1.0f - std::pow(keepPerSecond, dt) };
    return { from.x + (to.x - from.x) * t, from.y + (to.y - from.y) * t };
}

namespace
{
    float clampAxis(float v, float visible, float level)
    {
        if (level <= visible) return level / 2;
        return std::clamp(v, visible / 2, level - visible / 2);
    }
}

Vector2 clampToLevel(Vector2 target, float screenW, float screenH, float zoom, float levelW, float levelH)
{
    return { clampAxis(target.x, screenW / zoom, levelW), clampAxis(target.y, screenH / zoom, levelH) };
}

unitTests:
const Camera2D cam{ { 400, 225 }, { 1000, 500 }, 0, 2 };
TEST("world and screen") {
    Vector2 s = worldToScreen({ 1010, 490 }, cam); CHECK_NEAR(s.x, 420.0, 1e-4); CHECK_NEAR(s.y, 205.0, 1e-4);
    Vector2 w = screenToWorld({ 420, 205 }, cam); CHECK_NEAR(w.x, 1010.0, 1e-4); CHECK_NEAR(w.y, 490.0, 1e-4);
    w = screenToWorld({ 0, 0 }, cam); CHECK_NEAR(w.x, 800.0, 1e-4); CHECK_NEAR(w.y, 387.5, 1e-4);
}
TEST("dead zone") {
    Vector2 t = deadZone({ 100, 100 }, { 120, 90 }, 40, 30); CHECK_NEAR(t.x, 100.0, 1e-5); CHECK_NEAR(t.y, 100.0, 1e-5);
    t = deadZone({ 100, 100 }, { 160, 20 }, 40, 30); CHECK_NEAR(t.x, 120.0, 1e-5); CHECK_NEAR(t.y, 50.0, 1e-5);
}
TEST("smoothing is per second") {
    Vector2 a{ 0, 0 }; for (int i = 0; i < 60; ++i) a = smoothTowards(a, { 100, 0 }, 0.25f, 1.0f / 60);
    Vector2 b{ 0, 0 }; for (int i = 0; i < 20; ++i) b = smoothTowards(b, { 100, 0 }, 0.25f, 1.0f / 20);
    CHECK_NEAR(a.x, 75.0, 1e-2); CHECK_NEAR(b.x, 75.0, 1e-2);
}
TEST("inside the level") {
    Vector2 t = clampToLevel({ 50, 50 }, 800, 450, 1, 4000, 1000); CHECK_NEAR(t.x, 400.0, 1e-4); CHECK_NEAR(t.y, 225.0, 1e-4);
    t = clampToLevel({ 3900, 990 }, 800, 450, 2, 4000, 1000); CHECK_NEAR(t.x, 3800.0, 1e-4); CHECK_NEAR(t.y, 887.5, 1e-4);
    t = clampToLevel({ 50, 50 }, 800, 450, 1, 600, 2000); CHECK_NEAR(t.x, 300.0, 1e-4); CHECK_NEAR(t.y, 225.0, 1e-4);
}

